659	impl<'a, 'b, T: Item, D> Iterator for Cursor<'a, 'b, T, D>
660	where
661	    D: Dimension<'a, T::Summary>,
662	{
663	    type Item = &'a T;
664	
665	    fn next(&mut self) -> Option<Self::Item> {
666	        if !self.did_seek {
667	            self.next();
668	        }
669	
670	        if let Some(item) = self.item() {
671	            self.next();
672	            Some(item)
673	        } else {
674	            None
675	        }
676	    }
677	}
